export function InitialLoading({
  loaded = {{loaded}},
  style = "{{style}}",
  title = "{{title}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 18, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      {!loaded && (
        <>
          <div aria-hidden="true">
            {style === "skeleton" ? (
              <>
                <span style={{ display: "block", height: 12, background: "#24143014", borderRadius: 6, marginBottom: 8, width: "100%" }} />
                <span style={{ display: "block", height: 12, background: "#24143014", borderRadius: 6, marginBottom: 8, width: "60%" }} />
              </>
            ) : (
              <span className="spinner" style={{ display: "inline-block", width: 26, height: 26, border: "3px solid #24143022", borderTopColor: accent, borderRadius: 999 }} />
            )}
          </div>
          <p role="status" aria-live="polite">Loading your dashboard&hellip;</p>
        </>
      )}
      {loaded && (
        <>
          <h3 style={{ margin: "0 0 6px", color: "#241430" }}>{title}</h3>
          <p style={{ margin: 0 }}>Your dashboard is ready.</p>
        </>
      )}
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .spinner { animation: lod-init-spin 900ms linear infinite; }
          @keyframes lod-init-spin { to { transform: rotate(360deg); } }
        }
      `}</style>
    </div>
  );
}
